SELECT * FROM (SELECT e.event_id,'FOP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Furnace Charged' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='C')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'FOP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Heating Completed' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='A')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key UNION ALL SELECT e.event_id,'FOP:'||s.operation_id case_id,e.activity,e.timestamp FROM (SELECT 'FOP:'||operation_id event_id,'Furnace Discharged' activity,finished_at timestamp,operation_id source_key FROM furnace_operation_history WHERE finished_at IS NOT NULL AND (operation_code='D')) e JOIN furnace_operation_history s ON s.operation_id=e.source_key) ORDER BY case_id,timestamp,event_id;
